with base as (select *, case when page in ('/home', '/cart') then 'Tier 1' else 'Other' end as page_group, coalesce(page, 'OTHER') as page_clean from web_events where event_time >= date '2023-07-03' and page is not null) select * from (select page, session_id, event_type, duration_sec from base) src pivot (sum(duration_sec) as amount, count(1) as item_count for event_type in ('search', 'page_view'))
